void min_max(int a, int b, int *lo, int *hi) {
    if (a < b) {
        *lo = a;
        *hi = b;
    } else {
        *lo = b;
        *hi = a;
    }
}

int main() {
    int lo = 0;
    int hi = 0;
    min_max(9, 4, &lo, &hi);
    printf("lo=%d hi=%d\n", lo, hi);
    return 0;
}

