int fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);
}

int main() {
    printf("fact(5)=%d\n", fact(5));
    printf("fact(7)=%d\n", fact(7));
    return 0;
}

int memo[100];

int fib(int n) {
    if (n < 2) return n;
    if (memo[n] != -1) return memo[n];
    memo[n] = fib(n - 1) + fib(n - 2);
    return memo[n];
}

int main() {
    for (int i = 0; i < 100; i++) memo[i] = -1;
    printf("fib(10)=%d\n", fib(10));
    printf("fib(20)=%d\n", fib(20));
    return 0;
}

